INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000024f',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss artificial intelligence at B2","Use KI vocabulary","Talk about AI capabilities, risks, and governance"],"explanation":{"intro":"Artificial intelligence vocabulary covers AI capabilities, current debates, and governance challenges at B2.","culturalNote":"KI (Künstliche Intelligenz): Germany active in KI-Forschung (AI research). Key institutions: DFKI (Deutsches Forschungszentrum für Künstliche Intelligenz — German Research Center for AI, Kaiserslautern). EU AI Act (2024 — world''s first comprehensive AI regulation, risk-based approach — high risk AI requires conformity assessment). KI-Strategie (German AI strategy 2018). Key debates: Mensch-Maschine-Interaktion, Bias in KI-Systemen (bias in AI), Regulierung, Transparenz. GPT/LLMs — generative AI."},"examples":[{"german":"Die aktuellen Fortschritte in der generativen KI werfen grundlegende Fragen über die Grenzen zwischen menschlicher und maschineller Kreativität auf und fordern etablierte Berufs- und Eigentumskonzepte heraus.","english":"Current advances in generative AI raise fundamental questions about the boundaries between human and machine creativity and challenge established concepts of profession and property."},{"german":"Der EU AI Act versucht, einen risikobasierten Regulierungsrahmen zu etablieren, der KI-Innovationen fördert und gleichzeitig den Schutz von Grundrechten gewährleistet.","english":"The EU AI Act attempts to establish a risk-based regulatory framework that promotes AI innovations and at the same time guarantees the protection of fundamental rights."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss AI capabilities, the EU AI Act, and AI ethics at B2."}}',
'{"items":[{"word":"generativ","translation":"generative","pronunciation":"geh-neh-rah-TEEF","example":"Generative KI."},{"word":"maschinell","translation":"machine/mechanical","pronunciation":"ma-shi-NEL","example":"Maschinelle Kreativität."},{"word":"herausfordern","translation":"to challenge","pronunciation":"her-OWS-for-dern","example":"Konzepte herausfordern."},{"word":"risikobasiert","translation":"risk-based","pronunciation":"RIS-i-ko-bah-zeert","example":"Risikobasierter Ansatz."},{"word":"der Regulierungsrahmen","translation":"regulatory framework","pronunciation":"dayr reh-goo-LEER-oonks-rah-men","example":"Regulierungsrahmen etablieren."},{"word":"gewährleisten","translation":"to guarantee","pronunciation":"geh-VÄR-lys-ten","example":"Schutz gewährleisten."}]}',
'{"title":"Grundlegende Fragen aufwerfen — to raise fundamental questions (about established concepts)","pattern":"etwas wirft grundlegende Fragen auf über X = something raises fundamental questions about X (aufwerfen = to raise questions — separable; grundlegend = fundamental — implies the questions go to the root)","explanation":"Grundlegende Fragen aufwerfen = to raise fundamental questions (aufwerfen — separable: wirft auf, warf auf, hat aufgeworfen). Used when something prompts deep, structural questioning (not just minor doubts). The Fragen are über or nach something. Compare: in Frage stellen (to call into question — challenges an existing assumption directly), Bedenken aufwerfen (to raise concerns — more modest, less fundamental), Zweifel wecken (to arouse doubts — more personal, emotional response), thematisieren (to raise as a topic — more neutral).","examples":[{"sentence":"Die Forschungsergebnisse werfen grundlegende Fragen über die bisherigen Theorien auf.","translation":"The research results raise fundamental questions about previous theories."},{"sentence":"Diese Affäre wirft grundlegende Fragen über politische Integrität auf.","translation":"This affair raises fundamental questions about political integrity."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Generativ'' means?","options":["generative","generating","productive","creative"],"correctAnswer":"generative"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Current advances in generative AI raise fundamental questions about the boundaries between human and machine creativity and challenge established concepts of profession and property.","options":["Die aktuellen Fortschritte in der generativen KI werfen grundlegende Fragen über die Grenzen zwischen menschlicher und maschineller Kreativität auf und fordern etablierte Berufs- und Eigentumskonzepte heraus.","Generative KI verändert die Grenzen zwischen menschlicher und maschineller Kreativität.","KI stellt Berufe und Eigentumsrechte infrage.","Künstliche Intelligenz fordert gesellschaftliche Konzepte heraus."],"correctAnswer":"Die aktuellen Fortschritte in der generativen KI werfen grundlegende Fragen über die Grenzen zwischen menschlicher und maschineller Kreativität auf und fordern etablierte Berufs- und Eigentumskonzepte heraus."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Forschungsergebnisse werfen grundlegende Fragen über die bisherigen Theorien ___.","options":["auf","hervor","aus","ein"],"correctAnswer":"auf"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: This affair raises fundamental questions about political integrity","wordBankItems":["Diese","Affäre","wirft","grundlegende","Fragen","über","politische","Integrität","auf","."],"correctAnswer":"Diese Affäre wirft grundlegende Fragen über politische Integrität auf ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Gewährleisten'' means?","options":["to guarantee","to ensure","to secure","to assure"],"correctAnswer":"to guarantee"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000250',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss machine learning at B2","Use Machine Learning vocabulary","Talk about supervised learning, neural networks, and AI applications"],"explanation":{"intro":"Machine learning vocabulary covers core ML concepts, applications, and societal implications at B2.","culturalNote":"Machine Learning (ML): Teilgebiet der KI. Key concepts: überwachtes Lernen (supervised learning — labelled data), unüberwachtes Lernen (unsupervised), verstärkendes Lernen (reinforcement learning), neuronale Netze (neural networks), tiefes Lernen (deep learning). Applications in Germany: medizinische Diagnose, autonomes Fahren (VW, Mercedes, BMW), Sprachassistenten. Key issues: Trainingsdaten (training data), Overfitting, Bias im Datensatz (dataset bias), Erklärbarkeit (explainability — XAI). EU: ''right to explanation'' for automated decisions (GDPR Art. 22)."},"examples":[{"german":"Machine Learning ermöglicht Systemen, Muster aus Daten zu extrahieren, ohne explizit programmiert zu sein — ein fundamentaler Paradigmenwechsel gegenüber klassischer regelbasierter Programmierung.","english":"Machine learning enables systems to extract patterns from data without being explicitly programmed — a fundamental paradigm shift compared to classical rule-based programming."},{"german":"Die Qualität eines Machine-Learning-Modells hängt entscheidend von der Qualität der Trainingsdaten ab: Verzerrungen im Datensatz reproduzieren sich zwangsläufig in den Modellvorhersagen.","english":"The quality of a machine learning model depends crucially on the quality of the training data: biases in the dataset inevitably reproduce themselves in the model''s predictions."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss machine learning concepts, neural networks, and AI bias at B2."}}',
'{"items":[{"word":"extrahieren","translation":"to extract","pronunciation":"eks-trah-HEER-en","example":"Muster extrahieren."},{"word":"explizit","translation":"explicit/explicitly","pronunciation":"eks-pli-TSEET","example":"Nicht explizit programmiert."},{"word":"die Verzerrung","translation":"bias/distortion","pronunciation":"dee fer-TSER-roong","example":"Verzerrungen im Datensatz."},{"word":"reproduzieren","translation":"to reproduce","pronunciation":"reh-pro-doo-TSEER-en","example":"Sich reproduzieren."},{"word":"die Vorhersage","translation":"prediction","pronunciation":"dee FOR-hayr-zah-geh","example":"Modellvorhersagen."},{"word":"entscheidend","translation":"crucially/decisively","pronunciation":"ent-SHYDE-end","example":"Entscheidend abhängen von."}]}',
'{"title":"Entscheidend abhängen von — to depend crucially on","pattern":"etwas hängt entscheidend von X ab = something depends crucially on X (entscheidend = crucially/decisively — emphasises that X is the determining factor)","explanation":"Entscheidend von X abhängen = to depend crucially on X. Abhängen von (separable: hängt ab) + dative. Entscheidend (crucially, decisively) adds emphasis: X is THE determining factor, not just one of many. Compare: abhängen von (to depend on — neutral), stark abhängen von (to depend heavily on), von X bestimmt werden (to be determined by X — passive, more absolute), maßgeblich abhängen von (to depend substantially on — similar emphasis), in X liegen (to lie in X — identifying the key factor).","examples":[{"sentence":"Der Erfolg des Projekts hängt entscheidend von der Zusammenarbeit aller Beteiligten ab.","translation":"The project''s success depends crucially on the cooperation of all involved."},{"sentence":"Die Wirksamkeit der Therapie hängt entscheidend vom Zeitpunkt der Anwendung ab.","translation":"The effectiveness of the therapy depends crucially on the timing of its application."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Verzerrung'' means?","options":["bias/distortion","error","skew","deviation"],"correctAnswer":"bias/distortion"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The quality of a machine learning model depends crucially on the quality of the training data: biases in the dataset inevitably reproduce themselves in the model''s predictions.","options":["Die Qualität eines Machine-Learning-Modells hängt entscheidend von der Qualität der Trainingsdaten ab: Verzerrungen im Datensatz reproduzieren sich zwangsläufig in den Modellvorhersagen.","Schlechte Trainingsdaten führen zu schlechten KI-Modellen.","Bias in KI-Systemen entsteht oft durch unausgewogene Trainingsdaten.","KI-Modelle können nur so gut sein wie die Daten, mit denen sie trainiert werden."],"correctAnswer":"Die Qualität eines Machine-Learning-Modells hängt entscheidend von der Qualität der Trainingsdaten ab: Verzerrungen im Datensatz reproduzieren sich zwangsläufig in den Modellvorhersagen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Erfolg des Projekts hängt entscheidend von der Zusammenarbeit aller Beteiligten ___.","options":["ab","an","auf","bei"],"correctAnswer":"ab"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The effectiveness of the therapy depends crucially on the timing of its application","wordBankItems":["Die","Wirksamkeit","der","Therapie","hängt","entscheidend","vom","Zeitpunkt","der","Anwendung","ab","."],"correctAnswer":"Die Wirksamkeit der Therapie hängt entscheidend vom Zeitpunkt der Anwendung ab ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Extrahieren'' means?","options":["to extract","to mine","to retrieve","to derive"],"correctAnswer":"to extract"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000251',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss algorithmics at B2","Use Algorithmik vocabulary","Talk about algorithmic decision-making and bias"],"explanation":{"intro":"Algorithmics vocabulary covers algorithmic decision-making, societal impacts, and transparency demands at B2.","culturalNote":"Algorithmik und Gesellschaft: Algorithmen entscheiden zunehmend über Kreditwürdigkeit (creditworthiness), Einstellungsentscheidungen (hiring), Strafmaß (sentencing — US COMPAS algorithm, recidivism prediction). Key term: Algorithmusbias (algorithmic bias — reflects societal biases in training data). Forderungen nach: Transparenz (transparency), Erklärbarkeit (explainability), Auditierbarkeit (auditability), Diskriminierungsfreiheit. DSGVO Art. 22 (GDPR — right to human review for automated decisions). German Bundestag: Algorithm Council (Sachverständigenrat Algorithmik)."},"examples":[{"german":"Algorithmen sind nicht per se neutral: Sie spiegeln die Werte und Vorannahmen ihrer Ersteller sowie die sozialen Ungleichheiten wider, die in den Trainingsdaten kodiert sind.","english":"Algorithms are not neutral per se: they reflect the values and prior assumptions of their creators as well as the social inequalities encoded in the training data."},{"german":"Die Black-Box-Natur vieler KI-Algorithmen widerspricht dem Gebot der Transparenz und Nachvollziehbarkeit, das in einem Rechtsstaat an folgenreiche Entscheidungen gestellt werden muss.","english":"The black-box nature of many AI algorithms contradicts the requirement of transparency and comprehensibility that must be applied to consequential decisions in a state governed by law."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss algorithmic decision-making, algorithmic bias, and transparency requirements at B2."}}',
'{"items":[{"word":"per se","translation":"per se/in itself","pronunciation":"per zeh","example":"Nicht per se neutral."},{"word":"die Vorannahme","translation":"prior assumption","pronunciation":"dee FOR-an-nah-meh","example":"Vorannahmen der Ersteller."},{"word":"widerspiegeln","translation":"to reflect","pronunciation":"vi-der-SHPEE-geln","example":"Ungleichheiten widerspiegeln."},{"word":"die Nachvollziehbarkeit","translation":"comprehensibility/traceability","pronunciation":"dee NAKH-fol-tsee-bahr-kyt","example":"Transparenz und Nachvollziehbarkeit."},{"word":"folgenreich","translation":"consequential","pronunciation":"FOL-gen-rykh","example":"Folgenreiche Entscheidungen."},{"word":"der Rechtsstaat","translation":"state governed by law","pronunciation":"dayr REKHTS-shtaht","example":"Im Rechtsstaat."}]}',
'{"title":"Nicht per se — not per se, not in itself (challenging an unconditional assumption)","pattern":"nicht per se + adjective = not per se, not in itself X (per se = Latin: by itself/in itself; nicht per se challenges the assumption that something is inherently X)","explanation":"Nicht per se + adjective/noun = not per se, not inherently, not by itself (per se = Latin for ''through itself/by itself''; used in German and English). Algorithmen sind nicht per se neutral = Algorithms are not neutral per se. Challenges the assumption that something is unconditionally/automatically the case. Often followed by a colon or sondern explaining what makes it X in certain conditions. Compare: nicht automatisch (not automatically — weaker claim), nicht notwendigerweise (not necessarily — more formal), nicht zwangsläufig (not inevitably — more emphatic), nicht von Natur aus (not by nature — more biological/inherent).","examples":[{"sentence":"Wachstum ist nicht per se gut — es kommt auf die Art des Wachstums an.","translation":"Growth is not good per se — it depends on the type of growth."},{"sentence":"Technologie ist nicht per se ein Fortschritt für die Gesellschaft.","translation":"Technology is not per se a progress for society."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Folgenreich'' means?","options":["consequential","momentous","impactful","significant"],"correctAnswer":"consequential"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Algorithms are not neutral per se: they reflect the values and prior assumptions of their creators as well as the social inequalities encoded in the training data.","options":["Algorithmen sind nicht per se neutral: Sie spiegeln die Werte und Vorannahmen ihrer Ersteller sowie die sozialen Ungleichheiten wider, die in den Trainingsdaten kodiert sind.","Algorithmen sind nicht objektiv, sondern von menschlichen Werten geprägt.","KI-Algorithmen können Diskriminierung reproduzieren.","Bias in Algorithmen entsteht durch die Werte und Daten ihrer Entwickler."],"correctAnswer":"Algorithmen sind nicht per se neutral: Sie spiegeln die Werte und Vorannahmen ihrer Ersteller sowie die sozialen Ungleichheiten wider, die in den Trainingsdaten kodiert sind."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Wachstum ist nicht per se gut — es kommt auf die Art des Wachstums ___.","options":["an","ab","auf","dabei"],"correctAnswer":"an"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Technology is not per se a progress for society","wordBankItems":["Technologie","ist","nicht","per","se","ein","Fortschritt","für","die","Gesellschaft","."],"correctAnswer":"Technologie ist nicht per se ein Fortschritt für die Gesellschaft ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Vorannahme'' means?","options":["prior assumption","presupposition","precondition","premise"],"correctAnswer":"prior assumption"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000252',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss Big Data at B2","Use Big Data vocabulary","Talk about data collection, privacy, and analytics"],"explanation":{"intro":"Big Data vocabulary covers data collection, analysis, privacy concerns, and the value of data in the digital economy at B2.","culturalNote":"Big Data: three Vs: Volume (Datenmenge), Velocity (Verarbeitungsgeschwindigkeit), Variety (Verschiedenartigkeit). Germany: DSGVO (GDPR — Datenschutz-Grundverordnung 2018 — strongest data protection regulation globally). Key players: Google, Meta, Amazon, Alibaba. German debate: Datensouveränität (data sovereignty), Datenhoheit (data dominion), surveillance capitalism (Shoshana Zuboff — Überwachungskapitalismus). Key uses: personalisierte Werbung (targeted advertising), Kreditscoring, Gesundheitsforschung, Stadtplanung."},"examples":[{"german":"Die massenhafte Erhebung und Auswertung von Daten schafft eine neue Wirtschaftsform, in der persönliche Verhaltensdaten die wichtigste Rohstoffquelle darstellen.","english":"The mass collection and analysis of data creates a new form of economy in which personal behavioural data constitute the most important source of raw materials."},{"german":"Datenschutz und Datennutzung stehen in einem permanenten Spannungsverhältnis: Strenge Datenschutzregeln schützen Grundrechte, können aber Innovation und gesellschaftlichen Nutzen bremsen.","english":"Data protection and data use are in a permanent tension: strict data protection rules protect fundamental rights, but can slow down innovation and societal benefit."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Big Data, the GDPR, data sovereignty, and surveillance capitalism at B2."}}',
'{"items":[{"word":"die Erhebung","translation":"collection (of data)","pronunciation":"dee er-HAY-boong","example":"Massenhafte Erhebung."},{"word":"massenhaft","translation":"massive/mass","pronunciation":"MA-sen-haft","example":"Massenhafte Erhebung."},{"word":"die Rohstoffquelle","translation":"source of raw materials","pronunciation":"dee ROH-shtof-kvel-eh","example":"Rohstoffquelle der Digitalwirtschaft."},{"word":"das Spannungsverhältnis","translation":"tension","pronunciation":"dahs SHPAN-oonks-fer-hält-nis","example":"Permanentes Spannungsverhältnis."},{"word":"permanent","translation":"permanent/constant","pronunciation":"per-ma-NENT","example":"Permanentes Spannungsverhältnis."},{"word":"bremsen","translation":"to slow down/brake","pronunciation":"BREM-zen","example":"Innovation bremsen."}]}',
'{"title":"In einem permanenten Spannungsverhältnis stehen — to be in permanent tension (two values in structural conflict)","pattern":"A und B stehen in einem Spannungsverhältnis = A and B are in tension (Spannungsverhältnis = tension relationship — two principles or interests that pull against each other structurally)","explanation":"Spannungsverhältnis = tension (Spannung = tension + Verhältnis = relationship). In einem Spannungsverhältnis stehen = to be in tension with (structural, ongoing conflict between two values or interests). Permanentes Spannungsverhältnis = permanent tension (the conflict is irresolvable, not just temporary). Used in policy, ethics, and social analysis. Compare: im Widerspruch stehen zu (to be in contradiction to — more logical contradiction), konkurrieren mit (to compete with — more active), in Konflikt geraten mit (to come into conflict with — more specific/momentary).","examples":[{"sentence":"Sicherheit und Freiheit stehen in einem klassischen Spannungsverhältnis.","translation":"Security and freedom are in a classic tension."},{"sentence":"Wirtschaftswachstum und Umweltschutz stehen oft in einem Spannungsverhältnis.","translation":"Economic growth and environmental protection are often in tension."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Erhebung'' means?","options":["collection (of data)","survey","recording","gathering"],"correctAnswer":"collection (of data)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Data protection and data use are in a permanent tension: strict data protection rules protect fundamental rights, but can slow down innovation and societal benefit.","options":["Datenschutz und Datennutzung stehen in einem permanenten Spannungsverhältnis: Strenge Datenschutzregeln schützen Grundrechte, können aber Innovation und gesellschaftlichen Nutzen bremsen.","Datenschutz und Datennutzung lassen sich nicht immer vereinbaren.","DSGVO schützt Privatsphäre, kann aber Innovation hemmen.","Es gibt einen grundlegenden Konflikt zwischen Datenschutz und Datenverwertung."],"correctAnswer":"Datenschutz und Datennutzung stehen in einem permanenten Spannungsverhältnis: Strenge Datenschutzregeln schützen Grundrechte, können aber Innovation und gesellschaftlichen Nutzen bremsen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Sicherheit und Freiheit stehen in einem klassischen ___.","options":["Spannungsverhältnis","Konflikt","Widerspruch","Dilemma"],"correctAnswer":"Spannungsverhältnis"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Economic growth and environmental protection are often in tension","wordBankItems":["Wirtschaftswachstum","und","Umweltschutz","stehen","oft","in","einem","Spannungsverhältnis","."],"correctAnswer":"Wirtschaftswachstum und Umweltschutz stehen oft in einem Spannungsverhältnis ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Bremsen'' means?","options":["to slow down/brake","to impede","to hinder","to restrain"],"correctAnswer":"to slow down/brake"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000253',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss cybersecurity at B2","Use Cybersicherheit vocabulary","Talk about digital threats and protection"],"explanation":{"intro":"Cybersecurity vocabulary covers digital threats, critical infrastructure protection, and Germany''s security policy at B2.","culturalNote":"Cybersicherheit: key threat actors: staatliche Akteure (state actors — Russia, China, North Korea), Cyberkriminelle (cybercriminals — Ransomware), Hacktivisten. Key incidents affecting Germany: Hackerangriff auf Bundestag 2015 (Fancy Bear — Russian attribution), NotPetya 2017, Colonial Pipeline/fuel supply. Institutions: BSI (Bundesamt für Sicherheit in der Informationstechnik — Federal Office for Information Security, Bonn), Cybersicherheitsstrategie. Kritische Infrastruktur (KRITIS) protection. Key attacks: Phishing, Ransomware, DDoS, Supply chain attacks."},"examples":[{"german":"Cyberangriffe auf kritische Infrastrukturen — Energieversorgung, Wasserwerke, Krankenhäuser — sind nicht länger abstrakte Szenarien, sondern eine reale und zunehmend häufige Bedrohung.","english":"Cyberattacks on critical infrastructure — energy supply, waterworks, hospitals — are no longer abstract scenarios, but a real and increasingly frequent threat."},{"german":"Cybersicherheit erfordert eine kontinuierliche Anpassung an sich ständig verändernde Angriffsvektoren und kann kein statisches Schutzkonzept sein, das einmal konfiguriert und dann vergessen wird.","english":"Cybersecurity requires continuous adaptation to constantly changing attack vectors and cannot be a static protection concept that is configured once and then forgotten."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss cybersecurity threats, critical infrastructure, and Germany''s cyber policy at B2."}}',
'{"items":[{"word":"nicht länger","translation":"no longer","pronunciation":"nikht LENG-er","example":"Nicht länger abstrakt."},{"word":"die Bedrohung","translation":"threat","pronunciation":"dee beh-DROH-oong","example":"Reale Bedrohung."},{"word":"der Angriffsvektor","translation":"attack vector","pronunciation":"dayr AN-grifs-vek-tor","example":"Angriffsvektoren."},{"word":"die Anpassung","translation":"adaptation/adjustment","pronunciation":"dee AN-pa-soong","example":"Kontinuierliche Anpassung."},{"word":"konfigurieren","translation":"to configure","pronunciation":"kon-fi-goo-REER-en","example":"Einmal konfigurieren."},{"word":"kritisch","translation":"critical","pronunciation":"KRI-tish","example":"Kritische Infrastruktur."}]}',
'{"title":"Nicht länger — no longer (something previously true is no longer the case)","pattern":"etwas ist nicht länger X = something is no longer X (nicht länger = no longer — time-based negation: it was true before, it is no longer true now)","explanation":"Nicht länger + adjective/verb = no longer (stronger emphasis on the temporal shift than nicht mehr — conveys that a situation that WAS the case has definitively changed, often in argumentative or emphatic contexts). Cyberangriffe sind nicht länger abstrakte Szenarien = Cyberattacks are no longer abstract scenarios. Compare: nicht mehr (no longer — most neutral and common), nicht länger (no longer — emphasises the transition, slightly more formal/emphatic), nicht mehr ... (various — simple negation). In formal writing, nicht länger often appears when making an argumentative point: what was once seen as X is no longer X.","examples":[{"sentence":"Homeoffice ist nicht länger eine Ausnahme, sondern die Regel.","translation":"Working from home is no longer the exception, but the rule."},{"sentence":"Klimawandel ist nicht länger ein Problem für künftige Generationen — er ist schon da.","translation":"Climate change is no longer a problem for future generations — it is already here."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Bedrohung'' means?","options":["threat","danger","risk","menace"],"correctAnswer":"threat"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Cyberattacks on critical infrastructure — energy supply, waterworks, hospitals — are no longer abstract scenarios, but a real and increasingly frequent threat.","options":["Cyberangriffe auf kritische Infrastrukturen — Energieversorgung, Wasserwerke, Krankenhäuser — sind nicht länger abstrakte Szenarien, sondern eine reale und zunehmend häufige Bedrohung.","Kritische Infrastrukturen sind zunehmend durch Cyberangriffe gefährdet.","Angriffe auf Energieversorger und Krankenhäuser haben zugenommen.","Cybersicherheit ist für kritische Infrastruktur ein wichtiges Thema."],"correctAnswer":"Cyberangriffe auf kritische Infrastrukturen — Energieversorgung, Wasserwerke, Krankenhäuser — sind nicht länger abstrakte Szenarien, sondern eine reale und zunehmend häufige Bedrohung."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Homeoffice ist nicht länger eine Ausnahme, sondern die ___.","options":["Regel","Norm","Standard","Praxis"],"correctAnswer":"Regel"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Climate change is no longer a problem for future generations it is already here","wordBankItems":["Klimawandel","ist","nicht","länger","ein","Problem","für","künftige","Generationen","—","er","ist","schon","da","."],"correctAnswer":"Klimawandel ist nicht länger ein Problem für künftige Generationen — er ist schon da ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Anpassung'' means?","options":["adaptation/adjustment","adjustment","modification","alignment"],"correctAnswer":"adaptation/adjustment"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000254',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss digital ethics at B2","Use Digitalethik vocabulary","Talk about AI ethics, privacy, and tech governance"],"explanation":{"intro":"Digital ethics vocabulary covers ethical principles for technology design and governance at B2.","culturalNote":"Digitalethik: growing field. Key principles: Privacy by Design, Algorithmentransparenz (algorithmic transparency), digitale Würde (digital dignity), Datensouveränität. Key institutions: Datenethikkommission (Data Ethics Commission — German government body, report 2019), AI Ethics Guidelines (EU HLEG on AI 2019 — seven principles: human agency and oversight, robustness, privacy, transparency, diversity, societal wellbeing, accountability). Key thinker: Luciano Floridi (information ethics). German NGOs: AlgorithmWatch, Gesellschaft für Informatik."},"examples":[{"german":"Digitalethik entwickelt normative Rahmenbedingungen für den Entwurf und den Einsatz digitaler Technologien, die über bloße rechtliche Compliance hinausgehen.","english":"Digital ethics develops normative framework conditions for the design and deployment of digital technologies that go beyond mere legal compliance."},{"german":"Das Konzept der algorithmischen Fairness ist intern vielschichtig und läuft in Einzelfällen auf sich widersprechende Anforderungen hinaus: Was für Gruppe A fair erscheint, kann für Gruppe B diskriminierend sein.","english":"The concept of algorithmic fairness is internally multi-layered and in individual cases amounts to contradictory requirements: what appears fair for group A can be discriminatory for group B."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss digital ethics, algorithmic fairness, and tech governance at B2."}}',
'{"items":[{"word":"normativ","translation":"normative","pronunciation":"nor-mah-TEEF","example":"Normative Rahmenbedingungen."},{"word":"der Entwurf","translation":"design/draft","pronunciation":"dayr ENT-voorf","example":"Entwurf von Technologien."},{"word":"der Einsatz","translation":"deployment/use","pronunciation":"dayr YN-zats","example":"Einsatz digitaler Systeme."},{"word":"hinausgehen über","translation":"to go beyond","pronunciation":"hi-NOWS-gay-en ü-ber","example":"Über Compliance hinausgehen."},{"word":"vielschichtig","translation":"multi-layered","pronunciation":"FEEL-shikh-tikh","example":"Vielschichtiges Konzept."},{"word":"auf X hinauslaufen","translation":"to amount to X","pronunciation":"owf X hi-NOWS-lau-fen","example":"Auf Widersprüche hinauslaufen."}]}',
'{"title":"Auf etwas hinauslaufen — to amount to, to come down to (the eventual result)","pattern":"etwas läuft auf X hinaus = something amounts to X, comes down to X (separable: läuft hinaus; X is what it ultimately equals or produces)","explanation":"Auf etwas hinauslaufen = to amount to, to come down to (separable: läuft hinaus, lief hinaus, ist hinausgelaufen). Das läuft auf Widersprüche hinaus = That amounts to contradictions. Used when following the logic of something to its conclusion: it ends up meaning/requiring X. Compare: auf etwas hinweisen (to point to — less conclusive), bedeuten (to mean — more direct), ergeben (to produce/result in — similar but more neutral), letztlich ... bedeuten (ultimately mean).","examples":[{"sentence":"Im Endeffekt läuft das auf dasselbe hinaus.","translation":"In the end, that amounts to the same thing."},{"sentence":"Der Vorschlag läuft auf eine vollständige Neustrukturierung hinaus.","translation":"The proposal amounts to a complete restructuring."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Normativ'' means?","options":["normative","regulatory","prescriptive","standard-setting"],"correctAnswer":"normative"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Digital ethics develops normative framework conditions for the design and deployment of digital technologies that go beyond mere legal compliance.","options":["Digitalethik entwickelt normative Rahmenbedingungen für den Entwurf und den Einsatz digitaler Technologien, die über bloße rechtliche Compliance hinausgehen.","Digitalethik geht über gesetzliche Anforderungen hinaus.","Technologieentwicklung braucht ethische Leitlinien, nicht nur Gesetze.","Ethik in der Digitaltechnik betrifft mehr als nur rechtliche Pflichten."],"correctAnswer":"Digitalethik entwickelt normative Rahmenbedingungen für den Entwurf und den Einsatz digitaler Technologien, die über bloße rechtliche Compliance hinausgehen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Im Endeffekt läuft das auf dasselbe ___.","options":["hinaus","heraus","hervor","aus"],"correctAnswer":"hinaus"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The proposal amounts to a complete restructuring","wordBankItems":["Der","Vorschlag","läuft","auf","eine","vollständige","Neustrukturierung","hinaus","."],"correctAnswer":"Der Vorschlag läuft auf eine vollständige Neustrukturierung hinaus ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Vielschichtig'' means?","options":["multi-layered","complex","multifaceted","nuanced"],"correctAnswer":"multi-layered"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000255',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the platform economy at B2","Use Plattformökonomie vocabulary","Talk about digital platforms and market power"],"explanation":{"intro":"Platform economy vocabulary covers digital platforms, network effects, and market dominance at B2.","culturalNote":"Plattformökonomie: key players: Google (Alphabet), Amazon, Meta, Apple, Microsoft (GAFAM). Key concept: Netzwerkeffekte (network effects — the more users, the more valuable the platform), Zweiseitige Märkte (two-sided markets — platforms connecting two groups), Gatekeeping, Lock-in effects. EU regulation: Digital Markets Act (DMA 2022 — regulates ''Gatekeeper'' platforms), Digital Services Act (DSA). Germany: Bundeskartellamt (Federal Cartel Office) has been active in taking on platforms — Facebook market dominance ruling 2019."},"examples":[{"german":"Digitale Plattformen entfalten ihre Macht durch Netzwerkeffekte: Je mehr Nutzer eine Plattform hat, desto attraktiver wird sie für weitere Nutzer und desto schwieriger wird der Markteintritt für Wettbewerber.","english":"Digital platforms unfold their power through network effects: the more users a platform has, the more attractive it becomes for further users and the more difficult market entry becomes for competitors."},{"german":"Der Digital Markets Act der EU zielt darauf ab, die Torstenstellung digitaler Großplattformen einzuschränken und fairere Marktbedingungen für kleinere Wettbewerber zu schaffen.","english":"The EU''s Digital Markets Act aims to restrict the gatekeeping position of large digital platforms and to create fairer market conditions for smaller competitors."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the platform economy, network effects, and digital market regulation at B2."}}',
'{"items":[{"word":"entfalten","translation":"to unfold/develop","pronunciation":"ent-FAL-ten","example":"Macht entfalten."},{"word":"der Netzwerkeffekt","translation":"network effect","pronunciation":"dayr NETS-verk-ef-ekt","example":"Netzwerkeffekte."},{"word":"der Markteintritt","translation":"market entry","pronunciation":"dayr MARKT-yn-trit","example":"Markteintritt für Wettbewerber."},{"word":"der Wettbewerber","translation":"competitor","pronunciation":"dayr VET-beh-ver-ber","example":"Kleinere Wettbewerber."},{"word":"einschränken","translation":"to restrict","pronunciation":"YN-shren-ken","example":"Torstellung einschränken."},{"word":"desto ... je mehr","translation":"the more ... the more","pronunciation":"des-to ... yeh mayr","example":"Je mehr Nutzer, desto attraktiver."}]}',
'{"title":"Je ... desto — the more ... the more (correlative comparison)","pattern":"Je + comparative, desto + comparative (verb last in je-clause; verb moves to V2 in desto-clause)","explanation":"Je mehr/größer/..., desto mehr/attraktiver/... = the more/bigger..., the more/more attractive... Je mehr Nutzer eine Plattform hat, desto attraktiver wird sie = The more users a platform has, the more attractive it becomes. Structure: Je + comparative (verb to end of clause), desto + comparative (verb after adjective/adverb — position 2). Note: desto-clause has V2 word order (comparative moved to front acts as first element). Compare: umso + comparative (instead of desto — same meaning, regional preference in speech), im gleichen Maße wie (to the same extent as — less idiomatic), proportional zu (proportional to — more technical).","examples":[{"sentence":"Je mehr man übt, desto besser wird man.","translation":"The more one practises, the better one becomes."},{"sentence":"Je früher man beginnt, desto mehr Zeit bleibt übrig.","translation":"The earlier one starts, the more time remains."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Entfalten'' means?","options":["to unfold/develop","to expand","to deploy","to exert"],"correctAnswer":"to unfold/develop"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Digital platforms unfold their power through network effects: the more users a platform has, the more attractive it becomes for further users and the more difficult market entry becomes for competitors.","options":["Digitale Plattformen entfalten ihre Macht durch Netzwerkeffekte: Je mehr Nutzer eine Plattform hat, desto attraktiver wird sie für weitere Nutzer und desto schwieriger wird der Markteintritt für Wettbewerber.","Netzwerkeffekte machen große Plattformen noch mächtiger.","Digitale Plattformen nutzen Netzwerkeffekte, um Marktmacht aufzubauen.","Je größer eine Plattform, desto attraktiver für Nutzer und desto schwieriger für Konkurrenten."],"correctAnswer":"Digitale Plattformen entfalten ihre Macht durch Netzwerkeffekte: Je mehr Nutzer eine Plattform hat, desto attraktiver wird sie für weitere Nutzer und desto schwieriger wird der Markteintritt für Wettbewerber."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Je mehr man übt, desto besser ___ man.","options":["wird","ist","wächst","kann"],"correctAnswer":"wird"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The earlier one starts the more time remains","wordBankItems":["Je","früher","man","beginnt",",","desto","mehr","Zeit","bleibt","übrig","."],"correctAnswer":"Je früher man beginnt , desto mehr Zeit bleibt übrig ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Markteintritt'' means?","options":["market entry","market access","market penetration","entry into the market"],"correctAnswer":"market entry"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000256',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss automation and work at B2","Use Automatisierung vocabulary","Talk about labour market transformation"],"explanation":{"intro":"Automation and work vocabulary covers technological unemployment, skills transitions, and social policy responses at B2.","culturalNote":"Automatisierung und Arbeit: key studies: Frey/Osborne (2013 — 47% US jobs at risk of automation); McKinsey (2017 — 50% of tasks automatable). German context: Industrie 4.0 (fourth industrial revolution — smart manufacturing, IoT, cyber-physical systems), Kurzarbeit (short-time work — German model for preventing layoffs during disruption), IG Metall (Germany''s largest union — engaged with automation). Debate: Maschinensteuer (robot tax), Grundeinkommen (basic income), Umschulung (retraining), Qualifizierungsoffensive."},"examples":[{"german":"Automatisierung verdrängt nicht uniformly Arbeit, sondern verändert die Zusammensetzung der Beschäftigung: Routineaufgaben werden zunehmend automatisierbar, während soziale und kreative Tätigkeiten resilienter sind.","english":"Automation does not displace work uniformly, but changes the composition of employment: routine tasks become increasingly automatable, while social and creative activities are more resilient."},{"german":"Aktive Arbeitsmarktpolitik — Umschulung, Qualifizierung, Arbeitszeitreduzierung — kann die Friktionen technologischer Disruption abfedern, erfordert aber erhebliche staatliche Investitionen.","english":"Active labour market policy — retraining, upskilling, reduction of working hours — can cushion the frictions of technological disruption, but requires considerable state investments."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss automation''s impact on work, labour market policy, and Germany''s Industrie 4.0 at B2."}}',
'{"items":[{"word":"verdrängen","translation":"to displace/push out","pronunciation":"fer-DRENG-en","example":"Arbeit verdrängen."},{"word":"die Zusammensetzung","translation":"composition","pronunciation":"dee tsoo-ZA-men-zetsoong","example":"Zusammensetzung der Beschäftigung."},{"word":"resilient","translation":"resilient","pronunciation":"reh-zi-LEE-ent","example":"Resilienter gegenüber Automatisierung."},{"word":"die Umschulung","translation":"retraining","pronunciation":"dee OOM-shoo-loong","example":"Umschulung fördern."},{"word":"abfedern","translation":"to cushion/absorb","pronunciation":"AP-fay-dern","example":"Friktionen abfedern."},{"word":"die Friktion","translation":"friction","pronunciation":"dee frik-TSYOHN","example":"Friktionen der Disruption."}]}',
'{"title":"Nicht X, sondern verändert Y — not X but changes Y (correcting a common assumption)","pattern":"Automatisierung verdrängt nicht X, sondern verändert Y = Automation does not X, but changes Y (nicht...sondern corrects a misperception and offers the more accurate framing)","explanation":"Nicht X, sondern Y = not X, but Y (replacing a false or incomplete claim with the accurate one). Automatisierung verdrängt nicht uniformly Arbeit, sondern verändert die Zusammensetzung = Automation does not uniformly displace work, but changes the composition (the first claim X is falsified; Y is what actually happens). The nicht...sondern construction makes argumentative writing more precise. Compare: zwar X, aber nicht Y (X is true, but not Y — concessive rather than corrective), weder X noch Y (neither X nor Y), nicht nur X, sondern (auch) Y (not only X but also Y — additive, not corrective).","examples":[{"sentence":"Das Problem ist nicht Faulheit, sondern mangelnde Ressourcen.","translation":"The problem is not laziness, but lack of resources."},{"sentence":"Er hat nicht gezögert, sondern sorgfältig überlegt.","translation":"He did not hesitate, but carefully considered."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Verdrängen'' means?","options":["to displace/push out","to replace","to eliminate","to remove"],"correctAnswer":"to displace/push out"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Automation does not displace work uniformly, but changes the composition of employment: routine tasks become increasingly automatable, while social and creative activities are more resilient.","options":["Automatisierung verdrängt nicht uniformly Arbeit, sondern verändert die Zusammensetzung der Beschäftigung: Routineaufgaben werden zunehmend automatisierbar, während soziale und kreative Tätigkeiten resilienter sind.","Nicht alle Berufe sind gleichermaßen von Automatisierung bedroht.","Automatisierung ersetzt Routinearbeit, aber nicht kreative oder soziale Tätigkeiten.","Der Arbeitsmarkt verändert sich durch Automatisierung, aber Arbeit verschwindet nicht."],"correctAnswer":"Automatisierung verdrängt nicht uniformly Arbeit, sondern verändert die Zusammensetzung der Beschäftigung: Routineaufgaben werden zunehmend automatisierbar, während soziale und kreative Tätigkeiten resilienter sind."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Problem ist nicht Faulheit, sondern mangelnde ___.","options":["Ressourcen","Mittel","Möglichkeiten","Unterstützung"],"correctAnswer":"Ressourcen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He did not hesitate but carefully considered","wordBankItems":["Er","hat","nicht","gezögert",",","sondern","sorgfältig","überlegt","."],"correctAnswer":"Er hat nicht gezögert , sondern sorgfältig überlegt ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Abfedern'' means?","options":["to cushion/absorb","to buffer","to mitigate","to dampen"],"correctAnswer":"to cushion/absorb"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000257',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss data protection at B2","Use Datenschutz vocabulary","Talk about GDPR, privacy rights, and consent"],"explanation":{"intro":"Data protection vocabulary covers the GDPR, privacy rights, consent, and Germany''s strong data protection tradition at B2.","culturalNote":"Datenschutz in Deutschland: Germany is the birthplace of modern data protection. First data protection law: Hessen 1970. Federal law: BDSG (Bundesdatenschutzgesetz). EU: DSGVO (Datenschutz-Grundverordnung — GDPR 2016/2018) — strongest globally. Key principles: Zweckbindung (purpose limitation), Datensparsamkeit (data minimisation), Einwilligung (consent), Auskunftsrecht (right of access). German Datenschutzbeauftragte (Data Protection Commissioners) — state and federal. Max Schrems (Austrian activist — Schrems I, II — invalided EU-US data transfer agreements)."},"examples":[{"german":"Die DSGVO stärkt das Recht der Betroffenen auf informationelle Selbstbestimmung und verpflichtet Unternehmen zu Transparenz über Datenverarbeitungsprozesse, die für die durchschnittliche Person kaum nachvollziehbar sind.","english":"The GDPR strengthens the right of those affected to informational self-determination and obliges companies to transparency about data processing processes that are barely comprehensible for the average person."},{"german":"Das Spannungsverhältnis zwischen dem europäischen Datenschutzmodell und den Datenübertragungspraktiken amerikanischer Plattformunternehmen bleibt eines der drängendsten transatlantischen Regulierungsprobleme.","english":"The tension between the European data protection model and the data transfer practices of American platform companies remains one of the most pressing transatlantic regulatory problems."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the GDPR, informational self-determination, and EU-US data transfer at B2."}}',
'{"items":[{"word":"die informationelle Selbstbestimmung","translation":"informational self-determination","pronunciation":"dee in-for-mah-tsyo-NEL-eh ZELP-st-beh-STIM-oong","example":"Recht auf informationelle Selbstbestimmung."},{"word":"verpflichten zu","translation":"to oblige to","pronunciation":"fer-PFLIKH-ten tsoo","example":"Zu Transparenz verpflichten."},{"word":"kaum nachvollziehbar","translation":"barely comprehensible","pronunciation":"kowm NAKH-fol-tsee-bahr","example":"Kaum nachvollziehbar."},{"word":"drängend","translation":"pressing/urgent","pronunciation":"DREN-gend","example":"Drängendste Probleme."},{"word":"die Datenübertragung","translation":"data transfer","pronunciation":"dee DAH-ten-ü-ber-trah-goong","example":"Datenübertragungspraktiken."},{"word":"die Einwilligung","translation":"consent","pronunciation":"dee YN-vi-li-goong","example":"Einwilligung einholen."}]}',
'{"title":"Jemanden zu etwas verpflichten — to oblige someone to (something) / impose an obligation","pattern":"jemanden zu etwas verpflichten = to oblige someone to something (transitive — the actor imposes an obligation; verpflichtet werden zu = to be obliged to — passive)","explanation":"Verpflichten zu + dative = to oblige to, to impose an obligation to. Die DSGVO verpflichtet Unternehmen zu Transparenz = The GDPR obliges companies to transparency. Passive: Unternehmen werden zu Transparenz verpflichtet = Companies are obliged to transparency. Reflexive: sich verpflichten zu = to commit/pledge to (voluntary). Compare: zwingen zu (to force to — more coercive), auferlegen (to impose — more abstract obligation), müssen (must — less formal, describes the resulting obligation rather than imposing it).","examples":[{"sentence":"Das Gesetz verpflichtet Arbeitgeber zur Bereitstellung von Schutzausrüstung.","translation":"The law obliges employers to provide protective equipment."},{"sentence":"Das Unternehmen hat sich zu einer CO₂-neutralen Produktion bis 2035 verpflichtet.","translation":"The company has committed to CO₂-neutral production by 2035."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Drängend'' means?","options":["pressing/urgent","important","critical","immediate"],"correctAnswer":"pressing/urgent"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The GDPR strengthens the right of those affected to informational self-determination and obliges companies to transparency about data processing processes that are barely comprehensible for the average person.","options":["Die DSGVO stärkt das Recht der Betroffenen auf informationelle Selbstbestimmung und verpflichtet Unternehmen zu Transparenz über Datenverarbeitungsprozesse, die für die durchschnittliche Person kaum nachvollziehbar sind.","Die DSGVO schützt Datenschutzrechte und fordert Transparenz von Unternehmen.","Mit der DSGVO bekommen Bürger mehr Kontrolle über ihre Daten.","Unternehmen müssen nach DSGVO transparent über Datenverwertung informieren."],"correctAnswer":"Die DSGVO stärkt das Recht der Betroffenen auf informationelle Selbstbestimmung und verpflichtet Unternehmen zu Transparenz über Datenverarbeitungsprozesse, die für die durchschnittliche Person kaum nachvollziehbar sind."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Gesetz verpflichtet Arbeitgeber zur Bereitstellung von ___.","options":["Schutzausrüstung","Sicherheitsausrüstung","Schutzmitteln","Sicherheitsmitteln"],"correctAnswer":"Schutzausrüstung"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The company has committed to CO2-neutral production by 2035","wordBankItems":["Das","Unternehmen","hat","sich","zu","einer","CO₂-neutralen","Produktion","bis","2035","verpflichtet","."],"correctAnswer":"Das Unternehmen hat sich zu einer CO₂-neutralen Produktion bis 2035 verpflichtet ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Einwilligung'' means?","options":["consent","agreement","permission","approval"],"correctAnswer":"consent"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

-- Lesson 600: B2 Milestone 5 (xp:200, coins:100)
INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000258',1,'APPROVED','PUBLISHED',
'{"objectives":["Celebrate reaching 600 German lessons at B2","Review advanced digital and tech vocabulary","Demonstrate mastery of complex analytical German"],"explanation":{"intro":"You have completed 600 German lessons — a remarkable achievement! This milestone marks mastery of 200 B2 lessons covering advanced topics in politics, law, philosophy, history, and digital society.","culturalNote":"Meilenstein (milestone): literally ''milestone'' (Meile = mile + Stein = stone — the Roman milestones that marked distances on roads). In German, Meilenstein is used both literally and figuratively for significant achievements and turning points. At B2 level, you can now engage confidently with complex German texts, authentic media, and intellectual discourse on virtually any topic — a level of proficiency that few language learners reach. Glückwunsch zu diesem Meilenstein!"},"examples":[{"german":"Mit 600 Lektionen haben Sie nicht nur Sprachkenntnisse erworben, sondern auch ein tiefes Verständnis der deutschen Gesellschaft, Geschichte, Philosophie und Digitalpolitik entwickelt.","english":"With 600 lessons, you have not only acquired language knowledge, but also developed a deep understanding of German society, history, philosophy, and digital policy."},{"german":"Die Beherrschung einer Fremdsprache auf B2-Niveau bedeutet, dass Sie komplexe Texte verstehen, sich spontan und fließend ausdrücken und detaillierte Berichte zu einem breiten Themenspektrum verfassen können.","english":"Mastery of a foreign language at B2 level means that you can understand complex texts, express yourself spontaneously and fluently, and produce detailed reports on a wide range of topics."}],"rewards":{"xp":200,"coins":100},"metadata":{"estimatedMinutes":25,"canDo":"I can confidently discuss advanced German language topics at B2 level across science, technology, culture, politics, history, philosophy, and society."}}',
'{"items":[{"word":"der Meilenstein","translation":"milestone","pronunciation":"dayr MY-len-shtyn","example":"Einen Meilenstein erreichen."},{"word":"die Beherrschung","translation":"mastery","pronunciation":"dee beh-HER-shoong","example":"Sprachliche Beherrschung."},{"word":"spontan","translation":"spontaneously","pronunciation":"shpon-TAHN","example":"Spontan ausdrücken."},{"word":"fließend","translation":"fluently","pronunciation":"FLEE-send","example":"Fließend sprechen."},{"word":"das Themenspektrum","translation":"range of topics","pronunciation":"dahs TAY-men-shpek-troom","example":"Breites Themenspektrum."},{"word":"verfassen","translation":"to produce/write (formal)","pronunciation":"fer-FA-sen","example":"Berichte verfassen."}]}',
'{"title":"Nicht nur X erwerben, sondern auch Y entwickeln — not only acquire X but also develop Y","pattern":"nicht nur X, sondern auch Y (acquire/develop pattern) — used to show language learning produces both linguistic AND cultural/intellectual growth simultaneously","explanation":"Nicht nur X erworben, sondern auch Y entwickelt = not only acquired X, but also developed Y. The parallel structure (nicht nur ... sondern auch) with two parallel perfect participles (erworben, entwickelt) shows simultaneous achievements. This milestone grammar pattern combines: nicht nur...sondern auch (not only...but also) + parallel construction of haben + X participle ... auch Y participle. Used to articulate the multi-dimensional value of learning.","examples":[{"sentence":"Das Auslandsstudium hat ihr nicht nur Kenntnisse, sondern auch Selbstständigkeit und kulturelle Sensibilität gegeben.","translation":"The study abroad gave her not only knowledge, but also independence and cultural sensitivity."},{"sentence":"Die Reise hat uns nicht nur entspannt, sondern auch neue Perspektiven eröffnet.","translation":"The trip not only relaxed us but also opened up new perspectives."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Fließend'' means?","options":["fluently","smoothly","easily","flowing"],"correctAnswer":"fluently"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"With 600 lessons, you have not only acquired language knowledge, but also developed a deep understanding of German society, history, philosophy, and digital policy.","options":["Mit 600 Lektionen haben Sie nicht nur Sprachkenntnisse erworben, sondern auch ein tiefes Verständnis der deutschen Gesellschaft, Geschichte, Philosophie und Digitalpolitik entwickelt.","Nach 600 Lektionen beherrschen Sie Deutsch auf einem hohen Niveau.","600 Lektionen bringen tiefes Wissen über Sprache und Gesellschaft.","Sie haben Deutsch gelernt und gleichzeitig viel über Deutschland erfahren."],"correctAnswer":"Mit 600 Lektionen haben Sie nicht nur Sprachkenntnisse erworben, sondern auch ein tiefes Verständnis der deutschen Gesellschaft, Geschichte, Philosophie und Digitalpolitik entwickelt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Auslandsstudium hat ihr nicht nur Kenntnisse, sondern auch Selbstständigkeit und kulturelle Sensibilität ___.","options":["gegeben","gebracht","vermittelt","geschenkt"],"correctAnswer":"gegeben"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The trip not only relaxed us but also opened up new perspectives","wordBankItems":["Die","Reise","hat","uns","nicht","nur","entspannt",",","sondern","auch","neue","Perspektiven","eröffnet","."],"correctAnswer":"Die Reise hat uns nicht nur entspannt , sondern auch neue Perspektiven eröffnet ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Verfassen'' means?","options":["to produce/write (formal)","to compose","to author","to draft"],"correctAnswer":"to produce/write (formal)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

